Example: Mirroring Simstate of all power domains
The following example illustrates how to iterate and mirror the simstate of all the power
domains in the design:
Example 129 Mirroring Simstate of all power domains
upfPdSsObjT pd_ss_obj_array[0:4];
string mirrorNode = "pd_ss_obj_array";
int indx = 0;
upfHandleT design_handle = upf_get_handle_by_name("#UPFDESIGN#");
upfHandleT pd_iter =
upf_query_object_properties(design_handle,UPF_POWER_DOMAINS);
upfHandleT pd_handle = upf_iter_get_next(pd_iter);
while (pd_handle != upf_null)
upfBooleanT mirrorStatus;
string mirrorNodeSelect;
string mirrorIndex;
mirrorIndex.itoa(indx);
mirrorNodeSelect = $sformatf("%s[%s]", mirrorNode, mirrorIndex);

mirrorStatus =
upf_create_object_mirror(upf_query_object_pathname(pd_handle),
mirrorNodeSelect);
if (mirrorStatus == 1'b1) begin
$display("Power Domain '%s' mirror '%s' Successfull!",
upf_query_object_pathname(pd_handle), mirrorNodeSelect);
fork
automatic int index = indx;
automatic string select = mirrorNodeSelect;
automatic upfHandleT pdHandle = pd_handle;
forever begin
@(pd_ss_obj_array[index].current_simstate)
$display("Power Domain '%s' simstate
changed to %s\n", upf_query_object_pathname(pdHandle),
pd_ss_obj_array[index].current_simstate.name);
end
end
join_none
end
pd_handle = upf_iter_get_next(pd_iter);
indx = indx + 1;
end
end
