class Bus extends Config;
rand bit[9:0] addr;
constraint cstr {
soft addr[1:0] == 2'b0;
cfg[2] == 1'b0;
}
class BusA extends Bus;
rand bit[9:0] data;
constraint cstr {
addr inside { [0:255] } ;
data inside { [0:1023] } ;
}
class BusB extends Bus;
rand bit[7:0] data;
constraint cstr {
addr inside { [512:1023] };
data inside { [0:255] };
