BusB busB0 = new, busB1 = new;
Bus bus0 = new, bus1 = new;
initial begin
repeat(10) begin
busA0.randomize();
busA1.randomize();
busB0.randomize();
busB1.randomize();
bus0.randomize();
bus1.randomize();
end
end

